"use client";

import { useState, useRef, useEffect } from "react";
import Link from "next/link";

interface ActivityItem {
    id: string;
    title: string;
    slug: string;
}

interface ActivityCategory {
    id: string;
    name: string;
    slug: string;
    items: ActivityItem[];
}

export default function ActivitiesDropdown({ categories }: { categories: ActivityCategory[] }) {
    const [open, setOpen] = useState(false);
    const ref = useRef<HTMLDivElement>(null);

    useEffect(() => {
        function handleClick(e: MouseEvent) {
            if (ref.current && !ref.current.contains(e.target as Node)) {
                setOpen(false);
            }
        }
        document.addEventListener("mousedown", handleClick);
        return () => document.removeEventListener("mousedown", handleClick);
    }, []);

    return (
        <div ref={ref} className="relative">
            <button
                onClick={() => setOpen(!open)}
                onMouseEnter={() => setOpen(true)}
                className="hover:text-primary transition-colors flex items-center gap-1"
            >
                Үйл ажиллагаа
                <svg className={`w-3.5 h-3.5 transition-transform ${open ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                    <path d="M6 9l6 6 6-6" />
                </svg>
            </button>

            {open && (
                <div 
                    onMouseLeave={() => setOpen(false)}
                    className="absolute top-full left-1/2 -translate-x-1/2 mt-2 bg-white rounded-2xl shadow-2xl border border-slate-200 p-5 min-w-[420px] z-50 animate-in fade-in-0 slide-in-from-top-2"
                >
                    {categories.length === 0 ? (
                        <p className="text-sm text-slate-400 text-center py-4">Одоогоор чиглэл нэмэгдээгүй.</p>
                    ) : (
                        <div className="grid grid-cols-2 gap-6">
                            {categories.map(cat => (
                                <div key={cat.id}>
                                    <Link 
                                        href="/activities"
                                        onClick={() => setOpen(false)}
                                        className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3 block hover:text-primary transition-colors"
                                    >
                                        {cat.name}
                                    </Link>
                                    <div className="space-y-1.5">
                                        {cat.items.map(item => (
                                            <Link
                                                key={item.id}
                                                href={`/activities/${cat.slug}/${item.slug}`}
                                                onClick={() => setOpen(false)}
                                                className="block text-sm text-slate-700 hover:text-primary hover:bg-slate-50 rounded-lg px-2.5 py-1.5 -mx-1 transition-all"
                                            >
                                                {item.title}
                                            </Link>
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                    <div className="border-t border-slate-100 mt-4 pt-3">
                        <Link 
                            href="/activities" 
                            onClick={() => setOpen(false)}
                            className="text-xs font-semibold text-primary hover:underline"
                        >
                            Бүх үйл ажиллагаа →
                        </Link>
                    </div>
                </div>
            )}
        </div>
    );
}
